[BurstCompile]
struct MulJob : IJob
{
    [ReadOnly] public NativeArray<float> a, b;
    public NativeArray<float> c;

    public void Execute()
    {
        for (int i = 0; i < c.Length; i++)
            c[i] = a[i] * b[i];   // AVX2: 8 floats per vmulps
    }
}

// vectorizes: independent iterations, contiguous memory
for (int i = 0; i < n; i++) c[i] = a[i] * k + b[i];

// does not: early exit, the trip count is unknown
for (int i = 0; i < n; i++) { if (a[i] < 0f) break; c[i] = a[i]; }

// does not: each step needs the previous one
for (int i = 1; i < n; i++) a[i] = a[i - 1] * 0.5f + b[i];

// float sum: vectorizing it means reordering the additions
for (int i = 0; i < n; i++) sum += a[i];

// a static Burst method on raw pointers: Burst cannot know they don't overlap
[BurstCompile]
static unsafe class Kernels
{
    [BurstCompile]
    public static void Add([NoAlias] float* dst, [NoAlias] float* src, int n)
    {
        for (int i = 0; i < n; i++)
            dst[i] += src[i];   // promised no overlap: free to vectorize
    }
}

// in a job, NativeArray fields are NoAlias by default
struct AddJob : IJob
{
    public NativeArray<float> dst;
    [ReadOnly] public NativeArray<float> src;
    [NativeDisableContainerSafetyRestriction]
    public NativeArray<float> scratch;   // this one may alias the others
    public void Execute() { /* ... */ }
}

// a branch per element: SIMD lanes would need different paths
if (v > max) r = max; else r = v;

// both values are ready, a mask picks one: no jump
r = math.select(v, max, v > max);   // select(ifFalse, ifTrue, condition)

// the same for 4 lanes at once: v4 > max4 is a bool4
float4 r4 = math.select(v4, max4, v4 > max4);

[BurstCompile]
struct ClampSpeedJob : IJobFor
{
    public NativeArray<float> speed;
    public float maxSpeed;

    public void Execute(int i)
    {
        float s = speed[i];
        speed[i] = math.select(___, ___, s > maxSpeed);
    }
}

// scalar single: one float per instruction
vmulss  xmm0, xmm0, dword ptr [rcx + 4*rax]
// packed single, AVX: ymm = 256 bits = 8 floats
vmulps  ymm0, ymm0, ymmword ptr [rcx + 4*rax]
// SSE without the v prefix: xmm = 128 bits = 4 floats
mulps   xmm0, xmm1

